local _, WFJ = ...
WFJ.Data.add("spell", {
  [416002] = { "ブーツにGladiator Stanceのルーンを刻みます：\n\n$I1\n攻撃的なスタンスで、盾を装備している間の与えるダメージが$N1%増加し、ブロック率が$N2%上昇しますが、アーマーが$N3%、発生させる脅威が$N4%減少します。さらに、自分を狙っていない敵に自動攻撃でダメージを与えると、得る怒りが$N5%増加します。\n\nGladiator Stanceで盾を装備している間は、他のスタンス専用のアビリティもすべて使用できます。", nil, 0xa64ff401, nil, "um" },
  [416003] = { "手袋にSingle-Minded Furyのルーンを刻みます：\n\n$I1\n二刀流の間、移動速度が$N1%上昇し、近接の自動攻撃が直前の自動攻撃と同じ対象に命中するたびに攻撃速度が$N2%上昇します。最大$N3回まで累積します。$D1の間、または自動攻撃が別の対象に命中するまで持続します。", nil, 0x63801b3d, nil, "um" },
  [416004] = { "ベルトにBlood Surgeのルーンを刻みます：\n\n$I1\nHeroic Strike、Bloodthirst、Whirlwindに、$N1%の確率で$D1以内の次のSlamを即時にし、両方の近接武器で攻撃させ、怒りを消費しなくする効果が付きます。", nil, 0xf732cd1e, nil, "um" },
  [416005] = { "ベルトにPrecision Timingのルーンを刻みます：\n\n$I1\nSlamが即時になりますが、$D1のクールダウンが付きます。", nil, 0xef96d5a9, nil, "um" },
  [416008] = { "脚部にEverlasting Afflictionのルーンを刻みます：\n\n$I1\nDrain Life、Drain Soul、Shadowboltがダメージを与えるたびに、対象にかかっているCorruptionの効果時間が最大まで更新されます。", nil, 0x83f42112, nil, "um" },
  [416009] = { "胸部か法衣にDemonic Tacticsのルーンを刻みます：\n\n$I1\n悪魔が召喚されている間、自分と召喚した悪魔のすべての攻撃のクリティカル率が$N1%上昇します。", nil, 0x19bb25eb, nil, "um" },
  [416014] = { "ブーツにDemonic Knowledgeのルーンを刻みます：\n\n$I1\n悪魔のペットを召喚している間、自分と悪魔のペットの呪文ダメージが、自分のレベルの最大$N1%分増加します。", nil, 0x4f2489e2, nil, "um" },
  [416015] = { "腕甲にIncinerateのルーンを刻みます：\n\n$I1\n対象に$N1のFireダメージを与え、対象がImmolateを受けている場合はさらに$N2%のダメージを与えます。", nil, 0x296e95c6, nil, "um" },
  [416017] = { "ブーツにDance of the Wickedのルーンを刻みます：\n\n$I1\n敵にクリティカルを与えるたびに、自分と悪魔のペットは自分の呪文クリティカル率の$N1%に等しい回避率を得て、さらに両方とも最大マナの$N2%を回復します。", nil, 0xae65ca31, nil, "um" },
  [416028] = { "ブーツにSacred Shieldのルーンを刻みます：\n\n$I1\n対象はダメージを受けるたびにSacred Shieldを得て、$N1のダメージを吸収し、最大$D1の間、パラディンのFlash of Lightのクリティカル率が$N2%上昇します。さらに、Sacred Shieldを持つ対象へのFlash of Lightが、$D2かけてさらに$N4%回復するようになります。この効果は$D3に一度しか得られません。$D4持続します。この呪文は同時に一体の対象にしかかけられません。", nil, 0x84afb489, nil, "um" },
  [416031] = { "ブーツにThe Art of Warのルーンを刻みます：\n\n$I1\n与えるすべてのHolyダメージが$N1%増加し、近接攻撃と呪文のクリティカルでExorcismの残りクールダウンが$D1短縮されます。", nil, 0x36ce3657, nil, "um" },
  [416035] = { "ブーツにGuarded by the Lightのルーンを刻みます：\n\n$I1\n近接攻撃のBlocking後、$D2の間、$D1ごとに最大マナの$N1%を得ます。この効果はFlash of Light、Holy Light、Holy Shockを詠唱すると解除されます。", nil, 0x2f71e716, nil, "um" },
  [416042] = { "胸部か法衣にSurvival of the Fittestのルーンを刻みます：\n\n$I1\n近接攻撃でクリティカルヒットを受ける確率を$N1%減らし、受けるすべてのダメージを$N2%減らします。Bear FormかDire Bear Formの間、受けるダメージがさらに$N3%減少します。", nil, 0x4d8ef5c6, nil, "um" },
  [416044] = { "手袋にSunfireのルーンを刻みます：\n\n$I1\n敵を焼いて$N1のNatureダメージを与え、さらに$D1かけて$N2のNatureダメージを与えます。\n\nさらに、Bear Form、Cat Form、Dire Bear Formの間は、MoonfireがSunfire (Bear)またはSunfire (Cat)に置き換わります。この呪文は、Moonfireに関連するすべての効果の恩恵を受け、それらを発動させます。\n\nSunfire (Bear)\n敵を焼いて$N4のNatureダメージを与え、さらに$D2かけて$N5のNatureダメージを与えます。\n\nSunfire (Cat)\n敵を焼いて$N7のNatureダメージを与え、さらに$D3かけて$N8のNatureダメージを与えます。コンボポイントを$N10獲得します。", nil, 0xbed3fd8c, nil, "um" },
  [416046] = { "手袋にSkull Bashのルーンを刻みます：\n\n$I1\n13ヤード以内の対象に突進して頭蓋を打ち、呪文の詠唱を中断させ、$D1の間その系統の呪文を詠唱できなくします。Feral Chargeとクールダウンを共有します。", nil, 0xd5ab304e, nil, "um" },
  [416049] = { "脚部にLacerateのルーンを刻みます：\n\n$I1\n敵の対象を切り裂き、$D1かけて$N1のダメージと、対象にすでにあるLacerateの数ごとに$N3%の武器ダメージを出血で与えます。大量の脅威を発生させます。この効果は同じ対象に最大$N4回まで累積します。", nil, 0x38fe500a, nil, "um" },
  [416050] = { "胸部か法衣にLiving Seedのルーンを刻みます：\n\n$I1\n非周期の治療呪文で対象をクリティカル回復すると、回復量の$N1%分のLiving Seedを対象に植え付けます。Living Seedは、対象が次にダメージを受けるか非周期の治療を受けたときに花開きます。$D1持続します。", nil, 0x13ee1dbb, nil, "um" },
  [416051] = { "腕甲にElune's Firesのルーンを刻みます：\n\n$I1\n一部の呪文とアビリティが、対象にかかっているダメージと治療の持続効果の効果時間を延長します：\n\nStarfireはMoonfireを$D1延長します。\nWrathはSunfireを$D2延長します。\nRegrowthはRejuvenationを$D3延長します。\nShredはRipを$D4延長します。\n\n各効果は最初の効果時間までしか延長できません。", nil, 0x8484bc0a, nil, "um" },
  [416054] = { "ベルトにPower Surgeのルーンを刻みます：\n\n$I1\nFlame Shockがダメージを与えるたびに、$N1%の確率でLava BurstとChain Lightningのクールダウンをリセットし、$D1以内の次のLava BurstかChain Lightningを即時にします。Riptideが回復するたびに、$N3%の確率で$D2以内の次のChain Healを即時にします。さらに、$D3ごとに知力の$N6%に等しいマナを得ます。", nil, 0xce292ee1, nil, "um" },
  [416055] = { "兜にMental Dexterityのルーンを刻みます：\n\n$I1\n知力の$N1%に等しい分だけAttack Powerが増加します。", nil, 0xe5cd1b79, nil, "um" },
  [416057] = { "胸部か法衣にHealing Rainのルーンを刻みます：\n\n$I1\n対象のプレイヤーの周囲$N1ヤードの範囲を選び、その範囲内にいる、そのプレイヤーのパーティーメンバー全員を毎秒$N2回復します。", nil, 0x0154268c, nil, "um" },
  [416062] = { "外套にCoherenceのルーンを刻みます：\n\n$I1\nChain healの効果がジャンプごとに$N1%しか減らないようになり、Chain Lightningの効果がジャンプごとに$N2%しか減らないようになります。どちらも追加で$N3体の対象にジャンプします。", nil, 0xb0021a71, nil, "um" },
  [416066] = { "兜にBurnのルーンを刻みます：\n\n$I1\nFlame Shockが最大$N1体の対象に命中するようになり、効果時間が$D1延び、与えるダメージが$N3%増加します。さらに、装備したメインハンド武器にFlametongue Weaponが付与されている間、知力の$N4%に等しい呪文ダメージを得ます。", nil, 0xac8ad962, nil, "um" },
  [416083] = { "兜にCatlike Reflexesのルーンを刻みます：\n\n$I1\n自分の回避率が$N1%、ペットの回避率が$N2%上昇します。さらに、Flanking Strikeのクールダウンを$N3%短縮します。", nil, 0x62167ba0, nil, "um" },
  [416084] = { "ベルトにAspect of the Viperのルーンを刻みます：\n\n$I1\nハンターはヴァイパーのアスペクトをまとい、遠隔と近接の自動攻撃でマナが回復するようになりますが、与える総ダメージが$N1%減少します。さらに、$D1ごとに最大マナの$N2%を得ます。得るマナの量は武器の速度に基づきます。同時に有効にできるAspectは一つだけです。", nil, 0xbc7e4fbf, nil, "um" },
  [416085] = { "兜にLock and Loadのルーンを刻みます：\n\n$I1\n罠を設置するたびに、$D1以内の次のShot（Scatter Shotを除く）アビリティはマナを消費せず、クールダウンも発生しません。", nil, 0x8bef56d4, nil, "um" },
  [416086] = { "ベルトにMelee Specialistのルーンを刻みます：\n\n$I1\nRaptor Strikeが即時になり、Mongoose BiteとRaptor Strikeは攻撃ごとに$N1%の確率でMongoose BiteとRaptor Strikeのクールダウンをリセットします。", nil, 0xd798d541, nil, "um" },
  [416089] = { "ブーツにWyvern Strikeのルーンを刻みます：\n\n$I1\nWyvern StingのアビリティがWyvern Strikeに置き換わります。Wyvern Strikeは$N1%の武器ダメージを与え、対象を時間とともにBleedさせる強烈な一撃です。\n\nWyvern StrikeにはWyvern Stingのタレントが必要で、Survivalの呪文書にあるWyvern Stingのアビリティを置き換えます。", nil, 0x0a678dd2, nil, "um" },
  [416090] = { "兜にRapid Killingのルーンを刻みます：\n\n$I1\nRapid Fireのクールダウンを$D1短縮します。さらに、格下すぎない敵を倒すか、敵がSerpent Stingを受けたまま死ぬと、Rapid Killingを得て、$D2以内の次のShotアビリティのダメージが$N3%増加します。", nil, 0xbecee8c6, nil, "um" },
  [416091] = { "脚部にSniper Trainingのルーンを刻みます：\n\n$I1\n直前の$D1の間移動していないと、$N2%の確率でSniper's Aimを得ます。最大$N3回まで累積します。Sniper's AimはShotアビリティのクリティカル率を$N4%上昇させます。", nil, 0x5849af1c, nil, "um" },
  [416093] = { "腕甲にRaptor Furyのルーンを刻みます：\n\n$I1\nRaptor Strikeが、$D1の間、Raptor StrikeとMongoose Biteのダメージを$N1%増加させます。最大$N3回まで累積します。以後の効果は、この効果の持続時間を延長しません。", nil, 0x34e5d6c2, nil, "um" },
  [416288] = { "他の$N1枚の断片と組み合わせて、完全な地図を作ります。", nil, 0xdcc7f5cf, nil, "um" },
